insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('exam-anxiety', 'graduation-cap', 1, 'Емтихан алдындағы алаңдаушылық', 'Тревога перед экзаменом', 'Емтихан алдындағы толқу, ұйқысыздық және «бәрін ұмытып қаламын» деген қорқыныш.', 'Волнение, бессонница и страх «всё забуду» перед сессией.', '{"what":"Емтихан алдындағы алаңдаушылық — маңызды сынақ алдында дене мен ойдың күйзеліске беретін жауабы. Аздап толқу пайдалы: ол бойды жұмылдырады. Бірақ алаңдаушылық тым күшейсе, ол ойлауға, есте сақтауға және ұйқыға кедергі келтіре бастайды.","signs":["Жүрек қатты соғады, алақан терлейді, ішің ауырады немесе қолың дірілдейді.","Дайындалуға зейін қою қиын, ой бір жерден екінші жерге секіреді.","Емтихан алдындағы түні ұйқы келмейді.","«Бәрін ұмытып қаламын», «құлап қаламын» деген ойлар тоқтамайды.","Емтихан кезінде басың «бос» болып қалады."],"causes":["Баға мен нәтиже тым маңызды сияқты көрінеді.","Дайындық соңғы күндерге қалады да, бақылау сезімі жоғалады.","Өзіңді курстастарыңмен салыстыру толқуды күшейтеді.","Бұрынғы сәтсіз тәжірибе «тағы да солай болады» деген күтуді тудырады."],"tips":["Баяу тыныс ал: 4 санға дейін дем алып, одан ұзағырақ дем шығар. 3–5 минут жеткілікті.","Дайындықты күндерге бөл: бүгін қай тақырып және қанша уақыт екенін қағазға жаз.","Алаңдататын ойларыңды 10 минут бойы қағазға жаз: бұл басыңды жеңілдетеді.","Емтихан алдында ұйқыны қысқартпа: жақсы демалған ми тезірек есіне түсіреді.","Толқуды «жаман» деп емес, «дайындық энергиясы» деп қабылдап көр."],"specialist":"Егер алаңдаушылық бірнеше апта бойы өмірге кедергі келтірсе, үрей шабуылдары қайталанса немесе емтиханға бара алмайтындай болсаң, университет психологына немесе басқа маманға жүгін. Бұл әлсіздік емес, жеңілдікке жететін ең жылдам жол."}'::jsonb, '{"what":"Экзаменационная тревога — это реакция тела и мыслей на значимое испытание. Небольшое волнение полезно: оно мобилизует. Но если тревога становится слишком сильной, она мешает думать, запоминать и спать.","signs":["Сильно бьётся сердце, потеют ладони, болит живот или дрожат руки.","Трудно сосредоточиться на подготовке, мысли скачут.","Накануне экзамена не получается уснуть.","Мысли «всё забуду» и «провалюсь» не останавливаются.","Во время экзамена голова становится «пустой»."],"causes":["Оценка и результат кажутся слишком значимыми.","Подготовка откладывается на последние дни, и пропадает чувство контроля.","Сравнение с одногруппниками усиливает волнение.","Прошлый неудачный опыт рождает ожидание, что «снова будет так же»."],"tips":["Подыши медленно: вдох на 4 счёта, выдох подлиннее. Достаточно 3–5 минут.","Раздели подготовку по дням: какая тема сегодня и сколько времени — запиши на бумаге.","Выпиши тревожные мысли на 10 минут: так они «освобождают» голову.","Не урезай сон перед экзаменом: выспавшийся мозг вспоминает быстрее.","Попробуй назвать волнение не «плохим», а «энергией подготовки»."],"specialist":"Если тревога несколько недель мешает жить, повторяются панические приступы или ты не можешь прийти на экзамен, обратись к психологу вуза или другому специалисту. Это не слабость, а самый быстрый путь к облегчению."}'::jsonb)
on conflict (slug) do update set icon = excluded.icon, sort_order = excluded.sort_order, title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, content_kk = excluded.content_kk, content_ru = excluded.content_ru;

insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('motivation', 'flame', 2, 'Мотивацияның төмендеуі', 'Падение мотивации', 'Оқуға күш жоқ, бәрі мағынасыз сияқты, істер соңғы сәтке дейін кейінге қалады.', 'Нет сил учиться, всё кажется бессмысленным, дела откладываются на последний момент.', '{"what":"Мотивацияның төмендеуі — оқуға деген қызығушылық пен қуаттың азаюы. Ол көбіне шаршаудан, мақсаттың бұлыңғырлығынан немесе өзіңе тым қатты талап қоюдан туындайды. Бұл «жалқаулық» емес, ағзаның берген белгісі.","signs":["Тапсырманы бастау қиын, ал бастағаннан кейін де қызық болмайды.","Оқу мағынасыз сияқты көрінеді.","Істерді соңғы сәтке дейін кейінге қалдырасың, содан кейін өзіңді кінәлайсың.","Бұрын қуантатын нәрсе енді қызықтырмайды.","Шаршау демалғаннан кейін де кетпейді."],"causes":["Шаршау, ұйқы мен тамақтану режимінің бұзылуы.","Мақсат бұлыңғыр немесе тым алыс.","Тапсырма соншалық үлкен көрінеді, оған жақындаудың өзі қорқынышты.","Өзіңе тым қатал талап қою және қатты сынау."],"tips":["Тапсырманы 2 минуттық алғашқы қадамға кішірейт: дәптерді ашу, бір абзац оқу.","Таймерді 25 минутқа қойып, өзіңмен келіс: «тек осыны ғана істеймін».","Күн сайын бір кішкентай жеңісіңді жаз — тіпті «уақытында тұрдым» болса да.","Мақсатыңды жаз: осы оқудан нені алғың келеді?","Ұйқы, тамақ және қозғалыс — мотивацияның негізі, содан баста."],"specialist":"Егер қуаныш сезімі екі аптадан астам жоғалса, ештеңе қаламасаң, ұйқың немесе тәбетің күрт өзгерсе, маманға жүгін. Мәселе мотивацияда емес, жалпы күйіңде болуы мүмкін, оған қолдау қажет."}'::jsonb, '{"what":"Падение мотивации — это снижение интереса и энергии к учёбе. Чаще всего оно связано с усталостью, расплывчатой целью или слишком высокими требованиями к себе. Это не «лень», а сигнал организма.","signs":["Трудно начать задание, а начав — всё равно неинтересно.","Учёба кажется бессмысленной.","Дела откладываются до последнего, потом следует самокритика.","То, что раньше радовало, больше не увлекает.","Усталость не проходит даже после отдыха."],"causes":["Переутомление, сбитый режим сна и питания.","Цель размыта или слишком далека.","Задача кажется настолько огромной, что к ней страшно подступиться.","Слишком жёсткие требования к себе и самокритика."],"tips":["Сократи задачу до первого шага на 2 минуты: открыть тетрадь, прочитать абзац.","Поставь таймер на 25 минут и договорись с собой: «сделаю только это».","Каждый день записывай одну маленькую победу — даже «встал вовремя».","Запиши свою цель: что ты хочешь получить от этой учёбы?","Сон, еда и движение — основа мотивации, начни с них."],"specialist":"Если радость пропала больше чем на две недели, ничего не хочется, резко изменились сон или аппетит, обратись к специалисту. Возможно, дело не в мотивации, а в общем состоянии, которому нужна поддержка."}'::jsonb)
on conflict (slug) do update set icon = excluded.icon, sort_order = excluded.sort_order, title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, content_kk = excluded.content_kk, content_ru = excluded.content_ru;

insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('time-management', 'calendar-clock', 3, 'Уақытты жоспарлау', 'Планирование времени', 'Іс көп, уақыт аз: басымдықтарды қою және алаңдататын нәрселермен күресу.', 'Дел много, времени мало: расставляем приоритеты и справляемся с отвлечениями.', '{"what":"Уақытты жоспарлау — нені, қашан істейтініңді және нені қалдыратыныңды саналы түрде таңдау. Студенттерге бұл оңай емес: дәрістер, тапсырмалар, жұмыс, достар және шексіз ақпарат ағыны назар үшін таласады.","signs":["Апта соңында «күні бойы бос болмадым, бірақ ештеңе тындырмадым» деген сезім.","Тапсырмалар соңғы түнге жиналып қалады.","Маңыздыны шұғылдан ажырату қиын.","Телефон мен әлеуметтік желі оқуды үнемі бөлек-бөлек үзеді.","Демалуға да, оқуға да уақыт қалмайды."],"causes":["Жоспар жоқ немесе тым өршіл жоспар.","Тапсырмаға қанша уақыт кететінін қате бағалау.","Бірнеше істі бір мезгілде орындауға тырысу.","Алаңдататын нәрселер: хабарламалар, әлеуметтік желі, шу."],"tips":["Аптаны жексенбіде 15 минут жоспарла: 3 басты мақсат таңда.","Істерді Эйзенхауэр матрицасына орналастыр: маңызды мен шұғыл.","Күніне 1–3 басты міндетті белгіле, қалғаны — қосымша.","Оқып отырғанда телефонды басқа бөлмеге қой немесе «Мазаламаңыз» режимін қос.","Жоспарға демалыс пен ұйқыны да енгіз — олар да маңызды."],"specialist":"Егер жоспарлау мен зейін қоюдағы қиындықтар үнемі қайталанса және балалық шақтан бері байқалса, маманмен (психолог немесе невролог) кеңесіп көр: мұның зейін ерекшеліктеріне қатысы болуы мүмкін."}'::jsonb, '{"what":"Планирование времени — это осознанный выбор: что ты делаешь, когда и от чего отказываешься. Студентам это даётся непросто: лекции, задания, подработка, друзья и бесконечный поток информации борются за внимание.","signs":["К концу недели чувство: «весь день был занят, а ничего не сделал».","Задания накапливаются до последней ночи.","Трудно отличить важное от срочного.","Телефон и соцсети постоянно прерывают учёбу.","Не остаётся времени ни на отдых, ни на учёбу."],"causes":["Нет плана или план слишком амбициозный.","Неверная оценка времени, которое нужно на задачи.","Попытка делать несколько дел сразу.","Отвлекающие факторы: уведомления, соцсети, шум."],"tips":["Раз в неделю, например в воскресенье, потрать 15 минут на план: выбери 3 главные цели.","Разложи дела по матрице Эйзенхауэра: важное и срочное.","Отметь 1–3 главные задачи на день, остальное — дополнительное.","Во время учёбы убери телефон в другую комнату или включи режим «Не беспокоить».","Вноси в план отдых и сон — они тоже важны."],"specialist":"Если трудности с планированием и концентрацией постоянные и заметны с детства, стоит обсудить это со специалистом (психологом или неврологом): возможно, дело в особенностях внимания."}'::jsonb)
on conflict (slug) do update set icon = excluded.icon, sort_order = excluded.sort_order, title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, content_kk = excluded.content_kk, content_ru = excluded.content_ru;

insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('dormitory', 'users', 4, 'Жатақханадағы өмір', 'Жизнь в общежитии', 'Бөлмелеспен келісу, шекара қою және ортақ тұрмыс ережелері.', 'Договариваться с соседями, ставить границы и выстраивать общие правила быта.', '{"what":"Жатақханада тұру — жаңа тәжірибе: ортақ кеңістік, әртүрлі әдеттер мен өмір ырғағы. Жанжал көбіне үлкен мәселеден емес, уақытында айтылмай, жиналып қалған ұсақ реніштен туады.","signs":["Бөлмеге оралғың келмейді, себебі онда жағдай шиеленісті.","Реніш ішіңде жиналып, кейін кенеттен жарылып кетеді.","Жинау, шу және қонақтар туралы келісім жоқ.","Жеке орын мен уақыт жетпейді, оқуға да, демалуға да.","Бөлмелеспен қарым-қатынас дұшпандыққа немесе үнсіздікке айналады."],"causes":["Күн тәртібі мен тазалық туралы түсініктің әртүрлі болуы.","Ережелер туралы алдын ала келіспеу.","Тікелей айту қиын болғандықтан үнсіз қалу.","Шаршау мен оқу күйзелісі шыдамдылықты азайтады."],"tips":["Ортақ ережелерді бірге талқылаңдар: жинау, тыныштық, қонақтар, ортақ заттар.","Наразылығыңды «Мен-хабарлама» түрінде айт: «... болғанда мен ... сезінемін, маған ... керек».","Реніш жинақталмай тұрып, тыныш сәтті таңдап сөйлес.","Жеке уақыт пен орын туралы келісіңдер: құлаққап, кітапхана, серуен.","Өздерің шеше алмасаңдар, куратордан немесе коменданттан көмек сұра."],"specialist":"Егер жанжал қорлауға, қорқытуға, мүлікті бүлдіруге ұласса немесе қауіпсіздікке қатер төндірсе, бірден куратор мен жатақхана әкімшілігіне хабарла. Ұзақ созылған шиеленіс алаңдаушылық немесе қажығандық тудырса, психологқа жүгін."}'::jsonb, '{"what":"Жизнь в общежитии — новый опыт: общее пространство, разные привычки и ритмы. Конфликты чаще вырастают не из больших проблем, а из мелких обид, о которых вовремя не заговорили.","signs":["Не хочется возвращаться в комнату, потому что там напряжённо.","Обида копится внутри, а потом вдруг прорывается.","Нет договорённостей об уборке, шуме и гостях.","Не хватает места и времени побыть одному — и учиться, и отдыхать.","Отношения с соседом превращаются во вражду или молчание."],"causes":["Разный режим дня и разное представление о чистоте.","Заранее не договорились о правилах.","Говорить прямо трудно, поэтому молчим.","Усталость и учебный стресс снижают терпение."],"tips":["Обсудите общие правила вместе: уборка, тишина, гости, общие вещи.","Говори о претензии через «Я-сообщение»: «Я чувствую..., когда..., мне нужно...».","Заговаривай, пока обида не накопилась, и выбирай спокойный момент.","Договоритесь о личном времени и месте: наушники, библиотека, прогулка.","Если не получается самим, попроси помощи у куратора или коменданта."],"specialist":"Если конфликт переходит в оскорбления, угрозы, порчу вещей или угрожает безопасности, сразу сообщи куратору и администрации общежития. Если долгое напряжение вызывает тревогу или подавленность, обратись к психологу."}'::jsonb)
