insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('sleep-nutrition', 'moon', 5, 'Ұйқы мен тамақтану', 'Сон и питание', 'Ұйқы режимі, кофеин, экрандар және тамақтану тәртібі көңіл-күйге қалай әсер етеді.', 'Режим сна, кофеин, экраны и питание: как это влияет на состояние и настроение.', '{"what":"Ұйқы мен тамақтану — психикалық күйдің негізі. Студенттерде режим жиі бұзылады: кеш жатады, кеш тұрады, кофе мен энергетикпен жүреді, тамақты өткізіп жібереді. Бұл зейінге, көңіл-күйге және алаңдаушылыққа тікелей әсер етеді.","signs":["Кешке ұйықтау, таңертең тұру қиын.","Күндіз ұйқышылдық пен зейіннің төмендеуі.","Кофе мен энергетик көп ішіледі.","Тамақтану тәртіпсіз: таңғы ас жоқ, кешке артық жеу.","Көңіл-күй тез өзгереді, ашушаңдық пайда болады."],"causes":["Түннің бір уағына дейін дайындалу немесе экранға қарау.","Түстен кейінгі кофеин ұйқыға әсер етеді.","Тұрақты күн тәртібінің болмауы.","Ақша мен уақыт тапшылығынан тамақты өткізіп жіберу."],"tips":["Бір уақытта жатып, бір уақытта тұр — демалыс күндері де (±1 сағат).","Ұйқыға бір сағат қалғанда экрандарды өшіріп, жарықты әлсірет.","Түстен кейін кофе мен энергетик ішпе.","Таңғы асты ұмытпа және тамақты тәртіппен же.","Кешкі ырымды жаса: душ, кітап, қысқа тыныс жаттығуы."],"specialist":"Егер ұйқысыздық үш аптадан астам созылса, күндіз қатты ұйқы қысса, тәбет күрт өзгерсе немесе тамақ туралы ойлар өмірге кедергі келтірсе, дәрігерге немесе психологқа көріне бер."}'::jsonb, '{"what":"Сон и питание — основа психического состояния. У студентов режим часто сбивается: поздно ложатся и поздно встают, живут на кофе и энергетиках, пропускают еду. Это напрямую влияет на внимание, настроение и тревожность.","signs":["Трудно уснуть вечером и встать утром.","Днём сонливость и падение внимания.","Много кофе и энергетиков.","Беспорядочное питание: без завтрака, а вечером переедание.","Быстро меняется настроение, появляется раздражительность."],"causes":["Поздняя подготовка или экран допоздна.","Кофеин во второй половине дня влияет на сон.","Нет устойчивого распорядка дня.","Нехватка денег и времени, из-за чего еда пропускается."],"tips":["Ложись и вставай в одно время, в том числе в выходные (±1 час).","За час до сна выключи экраны и приглуши свет.","Не пей кофе и энергетики во второй половине дня.","Не забывай про завтрак и ешь по режиму.","Заведи вечерний ритуал: душ, книга, короткое дыхательное упражнение."],"specialist":"Если бессонница длится больше трёх недель, днём сильная сонливость, резко изменился аппетит или мысли о еде ухудшают жизнь, обратись к врачу или психологу."}'::jsonb)
