insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('career-anxiety', 'compass', 6, 'Мамандық туралы алаңдаушылық', 'Тревога о профессии', 'Мамандықты дұрыс таңдадым ба? Болашақ бұлыңғыр болғанда не істеуге болады.', 'Правильную ли специальность я выбрал(а)? Что делать, когда будущее неясно.', '{"what":"Мамандық туралы алаңдаушылық — болашақ жұмыс, табыс және «дұрыс таңдау» алдындағы қорқыныш. Ол көп студентке таныс: әлем тез өзгереді, ал «мінсіз таңдау» бар деген сенім қысым жасайды.","signs":["Болашақ туралы ойласаң, алаңдаушылық пайда болады.","Мамандықты қате таңдадым ба деп қорқасың.","Бес жылдан кейінгі өзіңді елестету қиын.","Өзіңді курстастарыңмен салыстырып, артта қалғандай сезінесің.","Болашақ туралы ойлар қазіргі оқуға кедергі келтіреді."],"causes":["«Бір рет және мәңгілікке таңдау керек» деген сенім.","Отбасы мен қоғамның күтулері.","Мамандықтар туралы нақты ақпарат пен тәжірибенің аздығы.","Басқалардың жетістіктерімен салыстыру."],"tips":["Құндылықтарыңды жаз: сен үшін не маңызды (еркіндік, табыс, адамдарға көмек, шығармашылық)?","Қызықтырған мамандықты бір ай сынап көр: маманмен сөйлес, шағын жоба жаса, тағылымдамаға бар.","«Мінсіз шешімді» емес, «келесі қадамды» таңда.","2–3 адамнан олардың жұмыс күні қалай өтетінін сұра.","Алаңдаған кезде денеге арналған тәсілдерді қолдан: тыныс алу, серуен, жазу."],"specialist":"Егер болашаққа алаңдау ұйқы мен оқуға жиі кедергі келтірсе, үмітсіздік сезімі пайда болса, университеттің мансап орталығына немесе психологқа жүгін."}'::jsonb, '{"what":"Тревога о профессии — это страх перед будущей работой, доходом и «правильным выбором». Она знакома многим студентам: мир быстро меняется, а вера в «идеальный выбор» создаёт давление.","signs":["При мыслях о будущем возникает тревога.","Страшно, что выбрал(а) не ту специальность.","Трудно представить себя через пять лет.","Сравниваешь себя с одногруппниками и чувствуешь, что отстаёшь.","Мысли о будущем мешают нынешней учёбе."],"causes":["Убеждение, что нужно выбрать один раз и навсегда.","Ожидания семьи и общества.","Мало реальной информации и опыта о профессиях.","Сравнение с чужими успехами."],"tips":["Выпиши свои ценности: что для тебя важно (свобода, доход, помощь людям, творчество)?","Устрой месяц проб: поговори со специалистом, сделай мини-проект, сходи на стажировку.","Выбирай не «идеальное решение», а «следующий шаг».","Расспроси 2–3 человек о том, как проходит их рабочий день.","Когда тревожно, обращайся к телесным практикам: дыхание, прогулка, письмо."],"specialist":"Если тревога о будущем регулярно мешает спать и учиться, появляется чувство безнадёжности, обратись в центр карьеры вуза или к психологу."}'::jsonb)
