insert into public.topics (slug, icon, sort_order, title_kk, title_ru, description_kk, description_ru, content_kk, content_ru)
values ('self-esteem', 'sparkles', 7, 'Өзін-өзі бағалау', 'Самооценка', 'Ішкі сыншы, салыстыру және өзіңе сенімсіздік. Күшті жақтарыңды көре білу.', 'Внутренний критик, сравнение с другими и неуверенность в себе. Как увидеть свои сильные стороны.', '{"what":"Өзін-өзі бағалау — өзің туралы ойың және өзіңе қатынасың. Ол «жақсымын» немесе «жаманмын» деген тұрақты жапсырма емес, жағдайға қарай өзгеріп отырады. Төмен өзін-өзі бағалау көбіне қатал ішкі сыншымен және салыстырумен байланысты.","signs":["Қателіктен кейін өзіңді ұзақ кінәлайсың.","Өзіңді басқалармен салыстырып, «мен нашармын» деп ойлайсың.","Мақтауды қабылдау қиын, оны «кездейсоқтық» деп есептейсің.","«Жоқ» деп айту немесе өз пікіріңді білдіру қиын.","Сәтсіздіктен қорқып, жаңа іске кіріспейсің."],"causes":["Балалық шақтағы және оқудағы сын мен салыстыру тәжірибесі.","Әлеуметтік желідегі «мінсіз» өмір бейнелері.","Перфекционизм: тек «ең жақсы» нәтиже ғана қабылданады.","Кемшіліктерге ғана назар аударып, күшті жақтарды байқамау."],"tips":["Күн сайын 3 нәрсені жаз: бүгін не жақсы шықты (кішкентай болса да).","Ішкі сынды естігенде өзіңнен сұра: «Досыма не айтар едім?»","Өзіңді өзіңмен салыстыр: бір жыл ішінде не үйрендің?","Күшті жақтарыңның тізімін жасап, әр апта сайын толықтыр.","Бір рет «жоқ» деп айтып көр — шағын нәрседен баста."],"specialist":"Егер «мен ешқайда жарамаймын» деген сезім ұзақ тұрса, көңіл-күй түссе, күш болмаса, жалғыздық пен қажетсіздік сезімі пайда болса, психологқа жүгін. Мұндай жағдайда қолдау шынымен көмектеседі."}'::jsonb, '{"what":"Самооценка — это то, что ты думаешь о себе и как к себе относишься. Это не постоянный ярлык «хороший» или «плохой», она меняется в зависимости от ситуации. Низкая самооценка часто связана со строгим внутренним критиком и сравнением с другими.","signs":["После ошибки долго себя винишь.","Сравниваешь себя с другими и думаешь «я хуже».","Трудно принимать похвалу, ты считаешь её «случайностью».","Трудно сказать «нет» или высказать своё мнение.","Не берёшься за новое, боясь неудачи."],"causes":["Опыт критики и сравнения в детстве и учёбе.","«Идеальные» образы в соцсетях.","Перфекционизм: принимается только «лучший» результат.","Фокус на недостатках, а сильные стороны остаются незамеченными."],"tips":["Каждый день записывай 3 вещи, которые сегодня получились (пусть маленькие).","Услышав внутреннюю критику, спроси себя: «Что бы я сказал(а) другу?».","Сравнивай себя с собой: чему ты научился(лась) за год?","Составь список своих сильных сторон и пополняй его каждую неделю.","Попробуй один раз сказать «нет» — начни с чего-то небольшого."],"specialist":"Если чувство «я никуда не гожусь» держится долго, настроение падает, нет сил, возникают одиночество и ощущение ненужности, обратись к психологу. В такой ситуации поддержка действительно помогает."}'::jsonb)
