insert into public.exercises (slug, type, title_kk, title_ru, description_kk, description_ru, instructions_kk, instructions_ru, duration_min, config, popular, status)
values ('breathing-478', 'breathing', '4-7-8 тыныс жаттығуы', 'Дыхание 4-7-8', 'Баяу тыныс жүйкені тыныштандырады. Емтихан алдында немесе ұйықтар алдында ыңғайлы.', 'Медленное дыхание помогает успокоить нервную систему. Подходит перед экзаменом и перед сном.', array['Ыңғайлап отыр, арқаңды түзе, иығыңды босат.', '4 санға дейін мұрыннан дем ал.', '7 санға дейін тыныс алмай кідір.', '8 санға дейін ауыздан баяу дем шығар.', 'Циклді 4 рет қайтала. Бас айналса, әдеттегі тынысқа орал.']::text[], array['Сядь удобнее, выпрями спину, расслабь плечи.', 'Вдохни носом на 4 счёта.', 'Задержи дыхание на 7 счётов.', 'Медленно выдохни ртом на 8 счётов.', 'Повтори цикл 4 раза. Если закружилась голова, вернись к обычному дыханию.']::text[], 3, '{"preset":"478","cycles":4}'::jsonb, true, 'published')
