insert into public.exercises (slug, type, title_kk, title_ru, description_kk, description_ru, instructions_kk, instructions_ru, duration_min, config, popular, status)
values ('breathing-box', 'breathing', '«Шаршы» тыныс алу', '«Квадратное» дыхание', 'Төрт тең бөліктен тұратын тыныс: дем алу, кідіру, дем шығару, кідіру. Зейінді жинайды.', 'Дыхание из четырёх равных частей: вдох, пауза, выдох, пауза. Помогает собраться.', array['Тік отыр, қолыңды тізеңе қой.', '4 санға дейін мұрыннан дем ал.', '4 санға дейін кідір.', '4 санға дейін дем шығар.', '4 санға дейін кідір де, циклді 5 рет қайтала.']::text[], array['Сядь прямо, положи руки на колени.', 'Вдохни носом на 4 счёта.', 'Задержи дыхание на 4 счёта.', 'Выдохни на 4 счёта.', 'Снова задержи на 4 счёта и повтори цикл 5 раз.']::text[], 3, '{"preset":"box","cycles":5}'::jsonb, true, 'published')
