insert into public.exercises (slug, type, title_kk, title_ru, description_kk, description_ru, instructions_kk, instructions_ru, duration_min, config, popular, status)
values ('grounding-54321', 'grounding', '5-4-3-2-1 техникасы', 'Техника 5-4-3-2-1', 'Алаңдаушылық басқанда назарды «осында және қазірге» қайтарудың қарапайым жолы.', 'Простой способ вернуть внимание «сюда и сейчас», когда накрывает тревога.', array['Айналаңа қара және көріп тұрған 5 затты ата.', 'Қолыңмен ұстай алатын 4 затты тап.', 'Естіп тұрған 3 дыбысты тыңда.', 'Сезіп тұрған 2 иісті ата.', 'Аузыңдағы 1 дәмді сезін де, баяу дем ал.']::text[], array['Оглядись и назови 5 вещей, которые видишь.', 'Найди 4 вещи, к которым можешь прикоснуться.', 'Прислушайся к 3 звукам.', 'Назови 2 запаха, которые чувствуешь.', 'Почувствуй 1 вкус во рту и медленно вдохни.']::text[], 5, '{}'::jsonb, true, 'published')
