insert into public.exercises (slug, type, title_kk, title_ru, description_kk, description_ru, instructions_kk, instructions_ru, duration_min, config, popular, status)
values ('emotion-diary', 'diary', 'Эмоциялар күнделігі', 'Дневник эмоций', 'Эмоцияны атап, күшін бағала, себебі мен ойды жаз. Уақыт өте келе заңдылықтар көрінеді.', 'Назови эмоцию, оцени силу, запиши причину и мысль. Со временем становятся видны закономерности.', array['Қазір сезініп тұрған эмоцияны таңда.', 'Оның күшін 1-ден 10-ға дейін бағала.', 'Не болғанын қысқаша жаз.', 'Басыңа қандай ой келгенін атап өт.', 'Қажет болса, ескертпе қалдыр және сақта.']::text[], array['Выбери эмоцию, которую чувствуешь сейчас.', 'Оцени её силу от 1 до 10.', 'Коротко запиши, что произошло.', 'Отметь, какая мысль пришла в голову.', 'При желании оставь заметку и сохрани.']::text[], 5, '{}'::jsonb, false, 'published')
