insert into public.articles (slug, title_kk, title_ru, excerpt_kk, excerpt_ru, body_kk, body_ru, today_steps_kk, today_steps_ru, tags_kk, tags_ru, sources, reading_time, status, published_at, topic_id)
values ('exam-day-calm', 'Емтихан қарсаңында және емтихан күні: денені де, ойды да қалай тыныштандыру', 'Накануне и в день экзамена: как успокоить тело и голову', 'Соңғы түн мен таңертеңгі сағаттарға арналған қарапайым әдістер және емтихан кезінде басың «бос» болып қалса не істеу керек.', 'Простые приёмы для последней ночи и утра и что делать, если во время экзамена голова вдруг «пустая».', 'Емтиханның алдындағы сағаттар көбіне ең алаңдатарлық болады. Мұнда мақсат — толқуды жою емес (оны жою мүмкін де емес), оны басқаруға болатын деңгейге түсіру.

## Алдыңғы кеш

- **Жаңа материалды оқуды тоқтат.** Кешкі сағаттарда тек негізгі схемалар мен қысқа конспектіге көз сал.
- **Заттарыңды дайында:** құжаттар, қалам, су, емтихан орнына бару жолы. Ертеңгі таңдағы шешімдер азайса, толқу да азаяды.
- **Ұйқыны қорға.** Түнгі оқу — қысқа мерзімде көмектескендей көрінеді, бірақ ұйқы жетіспесе, зейін мен есте сақтау нашарлайды. Жату уақытыңды әдеттегіден кешіктірме.
- Ұйқы келмесе, төсекте жата бермей, 10 минут тыныш бірдеңе істеп алып (кітап, жылы душ), қайта жат.

## Таңертең

Жеңіл таңғы ас іш, су ішіп ал. Кофені әдеттегіден көп ішпе: кофеин жүрек соғуын жиілетіп, толқу белгілерін күшейтуі мүмкін. Емтиханға асықпай жету үшін уақытты қорғап шық.

## Толқуды басқаша қабылда

Жүрек соғуы мен дірілді көпшілік «менде бірдеңе дұрыс емес» деп қабылдайды. Бірақ бұл дене сені әрекетке дайындап жатқанын білдіреді. Тәжірибелерде қатысушыларға «толқу белгілері сенің жағдайыңды жақсартады» деп түсіндіргенде, олар сынақта жақсы нәтиже көрсеткен (Jamieson және әріптестері, 2010). Өзіңе былай айтып көр: «Менің денем жұмылып жатыр. Бұл маған көмектеседі».

## Емтихан алдындағы 10 минуттық жазу

Кіру алдында күйзелісті өзіңе қағазға түсірудің пайдасы бар. Бір зерттеуде емтихан алдында 10 минут бойы алаңдататын ойлары туралы жазған студенттер, әсіресе алаңдаушылығы жоғары топта, нәтижені жақсартқан (Ramirez & Beilock, 2011). Қазір өзіңе: «Нені қорқамын? Ең жаман жағдай қандай, мен не істей аламын?» деп жаз.

## Емтихан кезінде

1. Барлық сұрақтарды бір рет оқып шық.
2. Түсінікті сұраққа алдымен жауап бер: бұл сенімді береді.
3. Басың «бос» болса, тоқта. 3 баяу тыныс ал, жадыңда барын қағазға ақтарып жаз — атау, формула, жылдар. Көбіне осыдан кейін жауап «ашылады».
4. Қатты алаңдасаң, **5-4-3-2-1** әдісін қолдан: бөлмедегі 5 затты көр, 4 нәрсені сезін, 3 дыбысты тыңда.
5. Қиын сұраққа тым ұзақ тұрып қалма: өткізіп жіберіп, соңында орал.

## Емтиханнан кейін

Нәтиже шыққанша достарыңмен әрбір жауапты талдауға асықпа: бұл көбіне алаңдаушылықты қайта күшейтеді. Демал, тамақтан, серуендеп ал. Сен істеуге болатынның бәрін істедің.

Алаңдаушылықты әрбір адам кейде сезінеді. Егер ол сенің өмірінді айтарлықтай шектесе, маманға жүгіну — ақылды шешім.', 'Часы перед экзаменом часто самые тревожные. Цель здесь не убрать волнение полностью (это невозможно), а снизить его до уровня, с которым можно работать.

## Накануне вечером

- **Прекрати изучать новый материал.** Вечером просмотри только основные схемы и короткий конспект.
- **Подготовь вещи:** документы, ручку, воду, маршрут до места экзамена. Чем меньше решений утром, тем меньше волнения.
- **Береги сон.** Ночная зубрёжка кажется выигрышем в краткосрочной перспективе, но при недосыпе внимание и память ухудшаются. Не ложись позже обычного.
- Если не получается уснуть, не лежи, мучаясь: займись 10 минут чем-то спокойным (книга, тёплый душ) и ложись снова.

## Утром

Позавтракай чем-нибудь лёгким, выпей воды. Не пей кофе больше, чем обычно: кофеин учащает сердцебиение и может усилить признаки волнения. Выйди из дома с запасом по времени, чтобы не спешить.

## Посмотри на волнение иначе

Учащённое сердцебиение и дрожь многие воспринимают как «со мной что-то не так». Но это тело готовит тебя к действию. В экспериментах участников, которым объясняли, что признаки волнения помогают справляться с задачей, лучше проходили тестирование (Jamieson и коллеги, 2010). Скажи себе: «Моё тело мобилизуется. Это мне помогает».

## Десять минут письма перед экзаменом

Выписать тревогу на бумагу перед входом тоже полезно. В одном исследовании студенты, которые перед экзаменом 10 минут писали о своих тревожных мыслях, улучшили результат, особенно в группе с высокой тревожностью (Ramirez & Beilock, 2011). Напиши: «Чего я боюсь? Что самое плохое может случиться и что я смогу сделать?»

## Во время экзамена

1. Один раз прочитай все вопросы.
2. Сначала отвечай на понятный вопрос: это добавляет уверенности.
3. Если голова «пустая», остановись. Сделай 3 медленных вдоха, выпиши на листе всё, что помнишь: термины, формулы, даты. Часто после этого ответ «открывается».
4. При сильной тревоге используй технику **5-4-3-2-1**: найди 5 предметов вокруг, 4 ощущения, 3 звука.
5. Не застревай на трудном вопросе слишком долго: пропусти и вернись в конце.

## После экзамена

Не спеши разбирать с одногруппниками каждый ответ, пока нет результата: это часто возвращает тревогу. Отдохни, поешь, прогуляйся. Ты сделал(а) всё, что мог(ла).

Тревогу время от времени чувствует каждый. Если она заметно ограничивает твою жизнь, обратиться к специалисту — разумное решение.', array['Ертеңгі емтихан заттарын дайында және жолды алдын ала жоспарла.', '10 минут бойы алаңдататын ойларыңды қағазға жаз.', '5-4-3-2-1 техникасын бір рет жаттықтыр, қажет кезде оңай істейтіндей болсын.']::text[], array['Подготовь вещи для экзамена и заранее продумай дорогу.', '10 минут запиши тревожные мысли на бумагу.', 'Один раз потренируй технику 5-4-3-2-1, чтобы в нужный момент она получалась легко.']::text[], array['емтихан', 'ұйқы', 'тыныс']::text[], array['экзамен', 'сон', 'дыхание']::text[], '["Ramirez, G., & Beilock, S. L. (2011). Writing about testing worries boosts exam performance in the classroom. Science, 331(6014), 211–213.","Jamieson, J. P., Mendes, W. B., Blackstock, E., & Schmader, T. (2010). Turning the knots in your stomach into bows: Reappraising arousal improves performance on the GRE. Journal of Experimental Social Psychology, 46(1), 208–212.","World Health Organization (2020). Doing What Matters in Times of Stress: An Illustrated Guide."]'::jsonb, 4, 'published', '2026-10-02T08:00:00Z', (select id from public.topics where slug = 'exam-anxiety'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, excerpt_kk = excluded.excerpt_kk, excerpt_ru = excluded.excerpt_ru, body_kk = excluded.body_kk, body_ru = excluded.body_ru, today_steps_kk = excluded.today_steps_kk, today_steps_ru = excluded.today_steps_ru, tags_kk = excluded.tags_kk, tags_ru = excluded.tags_ru, sources = excluded.sources, reading_time = excluded.reading_time, status = excluded.status, published_at = excluded.published_at, topic_id = excluded.topic_id;

