insert into public.articles (slug, title_kk, title_ru, excerpt_kk, excerpt_ru, body_kk, body_ru, today_steps_kk, today_steps_ru, tags_kk, tags_ru, sources, reading_time, status, published_at, topic_id)
values ('caffeine-screens-food', 'Кофе, экрандар және тамақтану тәртібі: өзіңді жақсы сезінуге не әсер етеді', 'Кофе, экраны и режим питания: что влияет на самочувствие', 'Энергетик пен түнгі лентаға балама тауып, тамақтануды студент бюджетіне ыңғайлы түрде реттеу жолдары.', 'Как заменить энергетики и ночную ленту и наладить питание с учётом студенческого бюджета.', 'Көңіл-күй мен зейін тек «ерік-жігерге» байланысты емес. Кофе, экран және тамақтану күн ішіндегі қуатқа елеулі әсер етеді. Төменде зерттеулерге сүйенген, бірақ қарапайым ұсыныстар бар. Бұл медициналық кеңес емес.

## Кофеин: пайдалы, бірақ шектеумен

Кофеин зейінді уақытша көтереді, бірақ оның әсері ағзада ұзақ тұрады: жартылай шығарылу уақыты орта есеппен бірнеше сағатты құрайды және адамнан адамға өзгереді. Сондықтан түстен кейінгі кофе түнгі ұйқыға әсер етуі мүмкін. Еуропалық тамақ қауіпсіздігі органы (EFSA, 2015) дені сау ересектер үшін тәулігіне **400 мг**-ға дейінгі кофеинді (шамамен 4 кесе кофеге тең) қауіпсіз деп санайды, ал жекелеген дозалар 200 мг-дан аспауы керек.

Энергетиктерде кофеин мен қант көп, ал алкогольмен араласқанда олар ағзаға қосымша жүктеме түсіреді. Сессия кезінде оларға сүйену «қарыз алып жұмыс істеу» сияқты: күші бүгін көбейеді, ал ертең шаршау күшейеді.

**Не істеуге болады:**

- кофені түске дейін ішуге тырыс;
- энергетикті су, айран немесе жеміс-жидекпен ауыстырып көр;
- сессияда ұйқыны кофеге ауыстырма.

## Экрандар: тек «көк жарық» емес

Кешкі уақытта жарық шығаратын құрылғыдан кітап оқу ұйқыға жатуды кідіртуі және таңертең ұйқышылдықты арттыруы мүмкін екені бір зерттеуде көрсетілген (Chang және әріптестері, 2015). Алайда ұйқыға әсер ететін тек жарық емес: лента мен бейнелер ойды қозғап, «тағы бір бейне» деп уақытты ұзартады.

**Не істеуге болады:**

- ұйқыға бір сағат қалғанда телефонды зарядқа қой, шамадан тыс жарықты азайт;
- түнгі режимді қос, бірақ ол негізгі шешім емес екенін есте сақта;
- төсекке жатқанда лентаны емес, қағаз кітапты немесе аудиокітапты таңда;
- телефонды төсектен алысқа қой, оянатын сағатты жеке сатып ал.

## Тамақтану: тәртіп — жетілдіруден маңызды

Студент өмірінде «мінсіз тамақтану» мүмкін емес, бірақ тұрақты тәртіп қуат тербелісін азайтады. Дүниежүзілік денсаулық сақтау ұйымының (ДДҰ) «Дұрыс тамақтану» ақпараттық парағында жемістер, көкөністер, дәнді дақылдар мен бұршақ тұқымдастарға көңіл бөлу ұсынылады, қант пен тұзды шектеу керек.

**Бюджетке ыңғайлы идеялар:**

- таңғы асқа: сұлы ботқасы, жұмыртқа, айран немесе қефир, нан және ірімшік;
- түскі асқа: қарақұмық, ноқат немесе жасымық, маусымдық көкөніс;
- тез жеңіл ас: банан, жаңғақтар, кептірілген жемістер, йогурт.

**Тәртіп:**

- таңғы астан бас тартпа: ол сенімді қуат береді;
- ұзақ аш қалып, кешке мол жеуден аулақ бол;
- күні бойы су ішіп жүр;
- ұйқыға жақын тым ауыр асты азайт.

## Бір мезгілде бәрін өзгертпе

Бір әдетті таңда және бір-екі апта сына. Мысалы, алдымен түстен кейінгі энергетикті сумен ауыстыр. Кейін таңғы астың тәртібін реттеп көр.

## Қашан көмек сұрау керек

Егер тамақ туралы ойлар үнемі алаңдатса, тамақтануды қатты шектеп немесе бақылаусыз жеп, кейін кінә сезінсең, ұйқың мен тәбетің күрт өзгерсе, дәрігерге немесе психологқа жүгін. Бұл әлсіздік емес, көмек алуға лайық жағдай.', 'Настроение и внимание зависят не только от «силы воли». Кофе, экраны и питание заметно влияют на энергию в течение дня. Ниже простые рекомендации, опирающиеся на исследования. Это не медицинский совет.

## Кофеин: полезен, но в меру

Кофеин временно повышает внимание, но действует в организме долго: период полувыведения в среднем составляет несколько часов и различается у разных людей. Поэтому кофе во второй половине дня может влиять на ночной сон. Европейское агентство по безопасности продуктов питания (EFSA, 2015) считает безопасным для здоровых взрослых потребление кофеина до **400 мг** в сутки (около 4 чашек кофе), а разовые дозы не должны превышать 200 мг.

В энергетиках много кофеина и сахара, а при сочетании с алкоголем они создают дополнительную нагрузку на организм. Опираться на них в сессию — всё равно что «работать в долг»: сегодня сил больше, завтра усталость сильнее.

**Что можно сделать:**

- пей кофе до обеда;
- попробуй заменить энергетик водой, айраном или фруктами;
- не заменяй сон кофе в сессию.

## Экраны: дело не только в «синем свете»

В одном исследовании показали, что чтение со светящегося экрана вечером может откладывать засыпание и усиливать утреннюю сонливость (Chang и коллеги, 2015). Но на сон влияет не только свет: лента и видео возбуждают, а «ещё одно видео» растягивает время.

**Что можно сделать:**

- за час до сна ставь телефон на зарядку и уменьшай яркость;
- включай ночной режим, но помни, что это не главное решение;
- в постели выбирай бумажную книгу или аудиокнигу вместо ленты;
- положи телефон подальше от кровати, а для подъёма купи отдельный будильник.

## Питание: режим важнее идеала

В студенческой жизни «идеальное питание» невозможно, но постоянный режим снижает колебания энергии. В информационном бюллетене Всемирной организации здравоохранения (ВОЗ) «Здоровое питание» рекомендуется делать упор на фрукты, овощи, цельные злаки и бобовые, а сахар и соль ограничивать.

**Идеи для небольшого бюджета:**

- на завтрак: овсянка, яйца, айран или кефир, хлеб с сыром;
- на обед: гречка, нут или чечевица, сезонные овощи;
- лёгкие перекусы: банан, орехи, сухофрукты, йогурт.

**Режим:**

- не пропускай завтрак: он даёт стабильную энергию;
- не допускай долгого голода с последующим перееданием вечером;
- пей воду в течение дня;
- уменьшай тяжёлую еду перед сном.

## Не меняй всё сразу

Выбери одну привычку и попробуй её одну-две недели. Например, сначала замени вечерний энергетик водой. Потом налаживай завтрак.

## Когда просить помощи

Если мысли о еде постоянно тревожат, ты сильно ограничиваешь себя в еде или не можешь остановиться, а потом испытываешь вину, резко изменились сон и аппетит, обратись к врачу или психологу. Это не слабость, а ситуация, в которой стоит получить помощь.', array['Бүгін түстен кейін кофе немесе энергетикті су не шайға ауыстыр.', 'Ертеңгі таңғы асты алдын ала жоспарла.', 'Ұйқыға бір сағат қалғанда телефонды төсектен алыс қой.']::text[], array['Сегодня после обеда замени кофе или энергетик водой или чаем.', 'Заранее спланируй завтрашний завтрак.', 'За час до сна положи телефон подальше от кровати.']::text[], array['кофеин', 'экрандар', 'тамақтану']::text[], array['кофеин', 'экраны', 'питание']::text[], '["EFSA Panel on Dietetic Products, Nutrition and Allergies (2015). Scientific Opinion on the safety of caffeine. EFSA Journal, 13(5), 4102.","Chang, A.-M., Aeschbach, D., Duffy, J. F., & Czeisler, C. A. (2015). Evening use of light-emitting eReaders negatively affects sleep, circadian timing, and next-morning alertness. PNAS, 112(4), 1232–1237.","World Health Organization (2020). Healthy diet. Fact sheet."]'::jsonb, 5, 'published', '2026-10-10T08:00:00Z', (select id from public.topics where slug = 'sleep-nutrition'))
