insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('exam-anxiety', 'Емтихан алдындағы алаңдаушылық деңгейі', 'Уровень экзаменационной тревоги', 'Соңғы екі аптадағы күйіңді ойла. 8 сұрақ, шамамен 3 минут. Жоғары ұпай алаңдаушылықтың жоғары екенін көрсетеді.', 'Вспомни последние две недели. 8 вопросов, около 3 минут. Высокий балл означает более сильную тревогу.', 3, '[{"level":"low","min":0,"max":8,"title_kk":"Төмен деңгей: алаңдаушылық басқарылады","title_ru":"Низкий уровень: тревога под контролем","summary_kk":"Жауаптарыңа қарағанда, емтихан алдындағы толқуың шамалы және дайындыққа кедергі келтірмейтін сияқты. Аздап толқу — сессияның қалыпты бөлігі, ол тіпті жинақталуға көмектеседі.","summary_ru":"Судя по ответам, волнение перед экзаменами у тебя умеренное и, скорее всего, не мешает подготовке. Небольшое волнение — нормальная часть сессии, оно даже помогает собраться.","recommendations_kk":["Ұйқы мен тамақтану режимін сақта: бұл — алаңдаушылықтан ең жақсы қорғаныс.","Дайындық жоспарын күндерге бөліп алдын ала жаса, бәрін соңғы аптаға жинама.","4-7-8 тыныс алуды үйреніп ал: толқу кенет күшейсе, көмектеседі."],"recommendations_ru":["Сохраняй режим сна и питания: это лучшая защита от тревоги.","Заранее составь план подготовки по дням, чтобы не копить всё на последнюю неделю.","Освой дыхание 4-7-8: пригодится, если волнение вдруг усилится."],"exercise_slugs":["breathing-478"],"specialist_kk":"Маманға жүгінудің қажеті жоқ шығар. Бірақ жағдайың өзгерсе, кейінге қалдырма.","specialist_ru":"Скорее всего, обращаться к специалисту не нужно. Но если состояние изменится, не откладывай."},{"level":"medium","min":9,"max":16,"title_kk":"Орташа деңгей: толқу байқалады","title_ru":"Средний уровень: волнение заметно","summary_kk":"Емтихан алдындағы толқу байқалады және кейде дайындыққа немесе ұйқыға кедергі келтіреді. Бұл жиі кездесетін жағдай, оны өз бетіңше қолдануға болатын тәсілдермен жеңуге болады.","summary_ru":"Волнение перед экзаменами заметно и временами мешает подготовке или сну. Это распространённая ситуация, и с ней можно справляться самостоятельными приёмами.","recommendations_kk":["Күніне 5 минут тыныс жаттығуын немесе 5-4-3-2-1 техникасын жаса.","Алаңдататын ойларды қағазға жазып, оларға деректермен жауап бер: шынымен не болуы мүмкін және сен не істей аласың?","Материалды шағын блоктарға бөліп, әрқайсысынан кейін ілгерілеуіңді белгіле."],"recommendations_ru":["Каждый день по 5 минут делай дыхательное упражнение или технику 5-4-3-2-1.","Выписывай тревожные мысли на бумагу и отвечай на них фактами: что реально может случиться и что ты можешь сделать.","Раздели материал на небольшие блоки и после каждого отмечай прогресс."],"exercise_slugs":["breathing-478","grounding-54321"],"specialist_kk":"Егер толқу бірнеше апта бойы тұрса немесе күшейсе, университет психологымен сөйлес.","specialist_ru":"Если волнение держится несколько недель или усиливается, поговори с психологом вуза."},{"level":"high","min":17,"max":24,"title_kk":"Жоғары деңгей: қолдау қажет болуы мүмкін","title_ru":"Высокий уровень: может понадобиться поддержка","summary_kk":"Емтихан алдындағы толқу қазір өте күшті және ұйқыға, көңіл-күйге, дайындыққа айтарлықтай әсер етіп жатыр. Бұл диагноз да, үкім де емес — саған қосымша қолдау қажет екенінің белгісі.","summary_ru":"Волнение перед экзаменами сейчас очень сильное и заметно влияет на сон, самочувствие и подготовку. Это не диагноз и не приговор — это сигнал, что тебе нужна дополнительная поддержка.","recommendations_kk":["Сенетін адаммен сөйлес: досыңмен, куратормен, отбасыңмен. Мұны іште ұстама.","Университет психологына жазыл — көбі тегін және құпия қабылдайды.","Күн сайын бір тыныштандыратын жаттығу жаса және ұйқыңды қорға."],"recommendations_ru":["Поговори с человеком, которому доверяешь: другом, куратором, родными. Не держи это в себе.","Запишись на консультацию к психологу вуза — многие принимают бесплатно и конфиденциально.","Каждый день делай одно успокаивающее упражнение и защищай свой сон."],"exercise_slugs":["breathing-box","grounding-54321","breathing-478"],"specialist_kk":"Тезірек психологқа немесе дәрігерге көріну ұсынылады, әсіресе алаңдаушылық ұйқыға, тамақтануға және емтиханға баруға кедергі келтірсе.","specialist_ru":"Рекомендуем в ближайшее время обратиться к психологу или врачу, особенно если тревога мешает спать, есть и ходить на экзамены."}]'::jsonb, 'published', (select id from public.topics where slug = 'exam-anxiety'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('motivation', 'Оқу мотивациясының деңгейі', 'Уровень учебной мотивации', 'Оқу қазір сені қаншалықты шабыттандыратынын бағала. 7 сұрақ, шамамен 3 минут. Жоғары ұпай мотивацияның жоғары екенін көрсетеді.', 'Оцени, насколько тебя сейчас вдохновляет учёба. 7 вопросов, около 3 минут. Высокий балл означает более высокую мотивацию.', 3, '[{"level":"low","min":0,"max":7,"title_kk":"Төмен деңгей: мотивация қазір аз","title_ru":"Низкий уровень: мотивации сейчас мало","summary_kk":"Қазір оқу саған қиын беріліп жатыр және қызығушылық аз. Бұл жалқаулық та, мінезің де емес: көбіне шаршау, мақсаттың бұлыңғырлығы немесе тым көп жүктеме себеп болады.","summary_ru":"Сейчас учёба даётся тебе с трудом и интереса мало. Это не лень и не твой характер: чаще причина в усталости, неясной цели или слишком большой нагрузке.","recommendations_kk":["Алдымен ұйқы, тамақ және серуенді қалпына келтір: мотивация шаршаған ағзада болмайды.","Тапсырманы 2 минуттық алғашқы қадамға кішірейтіп, Помодоро-таймермен 25 минут жұмыс істе.","Оқу мақсатыңды қағазға жазып, неге керек екенін өз сөзіңмен түсіндір."],"recommendations_ru":["Сначала восстанови сон, питание и прогулки: мотивации не бывает у уставшего организма.","Сократи задачу до первого шага на 2 минуты и поработай 25 минут с Помодоро-таймером.","Запиши свою учебную цель и объясни своими словами, зачем она тебе."],"exercise_slugs":["pomodoro","eisenhower-planner"],"specialist_kk":"Егер қуаныш сезімі екі аптадан астам болмаса, ұйқың немесе тәбетің өзгерсе, психологқа немесе дәрігерге жүгін.","specialist_ru":"Если радости нет больше двух недель, изменились сон или аппетит, обратись к психологу или врачу."},{"level":"medium","min":8,"max":14,"title_kk":"Орташа деңгей: мотивация ауытқиды","title_ru":"Средний уровень: мотивация колеблется","summary_kk":"Кейбір күндері оқуға бейімсің, кейде күш болмайды. Бұл қалыпты жағдай: мотивация тұрақты емес, оны шағын қадамдармен басқаруға болады.","summary_ru":"Бывают дни, когда ты вовлечён(а), и дни, когда сил нет. Это нормально: мотивация непостоянна, ею можно управлять небольшими шагами.","recommendations_kk":["Күн сайын 1–3 басты міндетті таңда және тек соларды міндетті деп есепте.","Күннің соңында бір кішкентай жеңісіңді жаз — прогресті көру күш береді.","Қиын тапсырманы ең жақсы жұмыс істейтін уақытыңа қой."],"recommendations_ru":["Выбирай на каждый день 1–3 главные задачи и считай обязательными только их.","В конце дня записывай одну маленькую победу: видеть прогресс — значит получать силы.","Ставь сложные задачи на то время суток, когда ты лучше всего работаешь."],"exercise_slugs":["pomodoro","eisenhower-planner"],"specialist_kk":"Егер құлдырау созылса немесе күшейсе, университет психологымен сөйлесу пайдалы.","specialist_ru":"Если спад затягивается или усиливается, полезно поговорить с психологом вуза."},{"level":"high","min":15,"max":21,"title_kk":"Жоғары деңгей: мотивация жақсы","title_ru":"Высокий уровень: мотивация хорошая","summary_kk":"Оқу саған негізінен қызығушылық пен мән береді. Енді басты міндет — қорыңды сақтап, күйіп кетпеу.","summary_ru":"Учёба в основном даёт тебе интерес и смысл. Теперь главная задача — беречь ресурс, чтобы не выгореть.","recommendations_kk":["Демалысты жоспарға қосыңыз: үзіліссіз жұмыс ұзақ мерзімде мотивацияны азайтады.","Жетістіктеріңді белгілеп отыр — бұл жалғастыруға күш береді.","Тәжірибеңмен курстастарыңа көмектесіп көр: оқыту өз түсінігіңді тереңдетеді."],"recommendations_ru":["Включай отдых в план: работа без перерывов со временем снижает мотивацию.","Отмечай свои достижения — это даёт силы продолжать.","Поделись опытом с одногруппниками: объясняя другим, ты глубже понимаешь тему."],"exercise_slugs":["pomodoro"],"specialist_kk":"Қазіргі жағдайда маманға жүгінудің қажеті жоқ шығар.","specialist_ru":"В нынешнем состоянии, скорее всего, обращаться к специалисту не нужно."}]'::jsonb, 'published', (select id from public.topics where slug = 'motivation'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('time-management', 'Уақытты басқару тиімділігі', 'Эффективность управления временем', 'Уақытыңды қалай жоспарлайтыныңды бағала. 7 сұрақ, шамамен 3 минут. Жоғары ұпай жоспарлаудың жақсы екенін көрсетеді.', 'Оцени, как ты планируешь своё время. 7 вопросов, около 3 минут. Высокий балл означает более эффективное планирование.', 3, '[{"level":"low","min":0,"max":7,"title_kk":"Төмен деңгей: жоспарлау қиын беріліп жатыр","title_ru":"Низкий уровень: планирование пока даётся трудно","summary_kk":"Қазір уақыт сені басқарып жатқан сияқты, керісінше емес. Бұл жиі кездеседі және үйренуге болады: жұмыс істейтін жүйені қадам-қадаммен құруға болады.","summary_ru":"Сейчас кажется, что время управляет тобой, а не ты им. Это частая ситуация, и этому можно научиться: рабочую систему строят шаг за шагом.","recommendations_kk":["Күніне тек 1–3 басты міндетті таңда және оларды таңертең жаз.","Істерді Эйзенхауэр матрицасына орналастыр: нені қазір істеу керек, нені жоспарлау керек.","Оқып отырғанда телефонды басқа бөлмеге қой немесе «Мазаламаңыз» режимін қос."],"recommendations_ru":["Выбирай на день только 1–3 главные задачи и записывай их утром.","Разложи дела по матрице Эйзенхауэра: что делать сейчас, а что запланировать.","На время учёбы убирай телефон в другую комнату или включай режим «Не беспокоить»."],"exercise_slugs":["eisenhower-planner","pomodoro"],"specialist_kk":"Егер қиындық бала кезден бері тұрақты болса және зейін қоюға қатты кедергі келтірсе, маманмен кеңесіп көр.","specialist_ru":"Если трудности постоянны с детства и сильно мешают концентрации, имеет смысл посоветоваться со специалистом."},{"level":"medium","min":8,"max":14,"title_kk":"Орташа деңгей: кейбір дағдылар бар","title_ru":"Средний уровень: часть навыков уже есть","summary_kk":"Жоспарлаудың кейбір тәсілдері өзіңде бар, бірақ жүйе әзірге тұрақты емес. Кішкентай жақсартулар үлкен нәтиже береді.","summary_ru":"Некоторые приёмы планирования у тебя уже есть, но система пока нестабильна. Небольшие улучшения дают заметный результат.","recommendations_kk":["Жексенбіде 15 минут бөліп, келесі апта үшін 3 мақсат жаз.","Алаңдататын нәрселердің тізімін жасап, ең көп уақыт алатын біреуін алып таста.","Жұмыс уақытыңды Помодоро-таймермен 25 + 5 минут түрінде өлше."],"recommendations_ru":["В воскресенье потрать 15 минут и запиши 3 цели на следующую неделю.","Составь список отвлекающих факторов и убери тот, что отнимает больше всего времени.","Измеряй рабочее время Помодоро-таймером: 25 минут работы и 5 минут отдыха."],"exercise_slugs":["eisenhower-planner","pomodoro"],"specialist_kk":"Маманға жүгінудің қажеті жоқ шығар; қиындық күшейсе, куратормен сөйлес.","specialist_ru":"Скорее всего, к специалисту обращаться не нужно; если трудности усилятся, поговори с куратором."},{"level":"high","min":15,"max":21,"title_kk":"Жоғары деңгей: жоспарлау жақсы","title_ru":"Высокий уровень: планирование на хорошем уровне","summary_kk":"Сен уақытыңды жақсы басқарасың: басымдықты қоясың және алаңдататын нәрселерді тежейсің. Ең бастысы — өзіңе демалыс қалдыру.","summary_ru":"Ты хорошо управляешь временем: расставляешь приоритеты и сдерживаешь отвлечения. Главное — не забывать оставлять время на отдых.","recommendations_kk":["Жоспардың ішінде «бос терезелер» қалдыр — күтпеген істерге орын болсын.","Жұмыс істейтін тәсілдеріңді курстастарыңмен бөліс.","Айына бір рет жоспарлау жүйеңді қайта қарап, ескіргенін өзгерт."],"recommendations_ru":["Оставляй в плане «окна» для неожиданных дел.","Поделись рабочими приёмами с одногруппниками.","Раз в месяц пересматривай свою систему и меняй то, что устарело."],"exercise_slugs":["pomodoro"],"specialist_kk":"Маманға жүгінудің қажеті жоқ.","specialist_ru":"Обращаться к специалисту не нужно."}]'::jsonb, 'published', (select id from public.topics where slug = 'time-management'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('dormitory', 'Бөлмелестермен қарым-қатынастағы жайлылық', 'Комфорт в общении с соседями', 'Жатақханадағы немесе пәтердегі бөлмелестермен қатынасыңды бағала. 7 сұрақ, шамамен 3 минут. Жоғары ұпай жайлылықтың жоғары екенін көрсетеді.', 'Оцени отношения с соседями по комнате в общежитии или квартире. 7 вопросов, около 3 минут. Высокий балл означает больший комфорт.', 3, '[{"level":"low","min":0,"max":7,"title_kk":"Төмен деңгей: қатынаста шиеленіс бар","title_ru":"Низкий уровень: в отношениях есть напряжение","summary_kk":"Қазір бөлмелестермен қарым-қатынас саған ауыр тиіп жатыр сияқты. Мұндай жағдайда жиналған реніштер шешімсіз қалғанда ғана күшейеді, ал сөйлесу жағдайды жиі өзгертеді.","summary_ru":"Сейчас отношения с соседями даются тебе тяжело. В такой ситуации обиды растут, пока их не обсудили, а разговор чаще всего меняет положение.","recommendations_kk":["Тыныш сәтті таңдап, бір нақты мәселені «Мен-хабарлама» түрінде айтып көр.","Ортақ ережелерді бірге жазып қойыңдар: жинау кестесі, тыныштық уақыты, қонақтар.","Жеке орын керек болса, кітапхананы, серуенді немесе құлаққапты пайдалан."],"recommendations_ru":["Выбери спокойный момент и скажи об одной конкретной проблеме через «Я-сообщение».","Запишите общие правила вместе: график уборки, время тишины, гости.","Если нужно личное пространство, используй библиотеку, прогулки или наушники."],"exercise_slugs":["emotion-diary","breathing-box"],"specialist_kk":"Егер шиеленіс қорлауға, қорқытуға немесе қауіпсіздікке қатер төндірсе, бірден куратор мен әкімшілікке хабарла. Ұзаққа созылса, психологқа жүгін.","specialist_ru":"Если напряжение переходит в оскорбления, угрозы или опасность, сразу сообщи куратору и администрации. Если оно затягивается, обратись к психологу."},{"level":"medium","min":8,"max":14,"title_kk":"Орташа деңгей: кейде қиындықтар бар","title_ru":"Средний уровень: бывают сложности","summary_kk":"Қарым-қатынаста жақсы жақтары да, шиеленісті сәттер де бар. Алдын ала келісім мен ашық сөйлесу жайлылықты арттырады.","summary_ru":"В отношениях есть и хорошие стороны, и напряжённые моменты. Заранее достигнутые договорённости и открытый разговор повышают комфорт.","recommendations_kk":["Айына бір рет 10 минут бөліп, не жақсы, не өзгерту керек екенін талқылаңдар.","Реніш пайда болғанда оны күндер бойы жинамай, сол күні немесе ертеңіне айт.","Эмоциялар күнделігіне ашуыңды жазып, оның себебін түсінуге тырыс."],"recommendations_ru":["Раз в месяц выделяйте 10 минут и обсуждайте, что хорошо и что стоит изменить.","Когда возникает обида, говори о ней в тот же день или на следующий, не копи.","Записывай раздражение в дневник эмоций и пробуй понять его причину."],"exercise_slugs":["emotion-diary"],"specialist_kk":"Маманға жүгінудің қажеті жоқ шығар; шиеленіс күшейсе, куратормен сөйлес.","specialist_ru":"Скорее всего, к специалисту обращаться не нужно; если напряжение усилится, поговори с куратором."},{"level":"high","min":15,"max":21,"title_kk":"Жоғары деңгей: қарым-қатынас жайлы","title_ru":"Высокий уровень: общение комфортное","summary_kk":"Бөлмелестермен қарым-қатынасың жақсы: келісімдер бар және сөйлесе аласыңдар. Бұл оқу мен демалысқа сенімді тірек береді.","summary_ru":"С соседями у тебя хорошие отношения: есть договорённости, и вы умеете разговаривать. Это надёжная опора для учёбы и отдыха.","recommendations_kk":["Жұмыс істеп тұрған ережелерді жазып қой — жаңа бөлмелес келсе, көмектеседі.","Жақсы сәттерді атап өт: алғыс айту қатынасты нығайтады.","Жеке уақытың мен ортақ уақыттың тепе-теңдігін сақта."],"recommendations_ru":["Запиши правила, которые работают: они помогут, если появится новый сосед.","Замечай хорошее: благодарность укрепляет отношения.","Сохраняй баланс между личным и общим временем."],"exercise_slugs":["emotion-diary"],"specialist_kk":"Маманға жүгінудің қажеті жоқ.","specialist_ru":"Обращаться к специалисту не нужно."}]'::jsonb, 'published', (select id from public.topics where slug = 'dormitory'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('sleep-nutrition', 'Ұйқы мен тамақтану режимінің сапасы', 'Качество режима сна и питания', 'Соңғы екі аптадағы әдеттеріңді ойла. 8 сұрақ, шамамен 3 минут. Жоғары ұпай режимнің жақсы екенін көрсетеді.', 'Вспомни свои привычки за последние две недели. 8 вопросов, около 3 минут. Высокий балл означает более здоровый режим.', 3, '[{"level":"low","min":0,"max":8,"title_kk":"Төмен деңгей: режим бұзылған","title_ru":"Низкий уровень: режим сбит","summary_kk":"Қазір ұйқы мен тамақтану режимің тұрақсыз сияқты. Бұл көңіл-күйге, зейінге және алаңдаушылыққа әсер етуі мүмкін. Жақсы жаңалық: режимді шағын қадамдармен жөндеуге болады.","summary_ru":"Сейчас режим сна и питания у тебя нестабилен. Это может влиять на настроение, внимание и тревожность. Хорошая новость: режим можно выправить небольшими шагами.","recommendations_kk":["Бір нәрседен баста: әр күні бір уақытта тұр, ұйқы өзі реттеле бастайды.","Ұйқыға бір сағат қалғанда экрандарды өшір, түстен кейін кофеиннен бас тарт.","Күнде таңертең қарапайым таңғы ас іш — тіпті кішкентай болса да."],"recommendations_ru":["Начни с одного: вставай каждый день в одно время, и сон начнёт выравниваться.","За час до сна выключай экраны и откажись от кофеина после обеда.","Каждое утро ешь простой завтрак — даже небольшой."],"exercise_slugs":["breathing-478","breathing-box"],"specialist_kk":"Егер ұйқысыздық үш аптадан астам созылса немесе тәбет күрт өзгерсе, дәрігерге немесе психологқа көріне бер.","specialist_ru":"Если бессонница длится больше трёх недель или резко изменился аппетит, обратись к врачу или психологу."},{"level":"medium","min":9,"max":16,"title_kk":"Орташа деңгей: режим жартылай тұрақты","title_ru":"Средний уровень: режим частично стабилен","summary_kk":"Кейбір әдеттерің жақсы, кейбіреулері жетілдіруді қажет етеді. Бір-екі өзгеріс көңіл-күйің мен қуатыңды байқарлықтай жақсартуы мүмкін.","summary_ru":"Часть привычек у тебя хорошая, часть требует доработки. Одно-два изменения могут заметно улучшить настроение и энергию.","recommendations_kk":["Әлсіз тұсыңды тап (ұйқы уақыты, экран, кофе, таңғы ас) және тек соны өзгертуден баста.","Кешкі ритуал жаса: душ, кітап, қысқа тыныс жаттығуы.","Демалыс күндері де ұйқы уақытын 1 сағаттан артық өзгертпе."],"recommendations_ru":["Найди слабое место (время сна, экран, кофе, завтрак) и меняй только его.","Заведи вечерний ритуал: душ, книга, короткое дыхательное упражнение.","В выходные не сдвигай время сна больше чем на час."],"exercise_slugs":["breathing-478"],"specialist_kk":"Маманға жүгінудің қажеті жоқ шығар; жағдай нашарласа, дәрігермен кеңес.","specialist_ru":"Скорее всего, к специалисту обращаться не нужно; если станет хуже, посоветуйся с врачом."},{"level":"high","min":17,"max":24,"title_kk":"Жоғары деңгей: режим жақсы","title_ru":"Высокий уровень: режим хороший","summary_kk":"Сенің ұйқы мен тамақтану режимің тұрақты. Бұл көңіл-күй мен оқу қуатының берік негізі.","summary_ru":"Твой режим сна и питания стабилен. Это надёжная основа для настроения и учебной энергии.","recommendations_kk":["Сессия кезінде де режимді сақтауға тырыс — ол ең қымбат ресурс.","Жұмыс істейтін әдеттеріңді жазып қой, қиын кезеңде оларға оралуға оңай болады.","Достарыңмен әдеттерің туралы бөліс — бірге ұстану жеңілірек."],"recommendations_ru":["Старайся сохранять режим и в сессию: это самый ценный ресурс.","Запиши рабочие привычки, чтобы легко вернуться к ним в трудный период.","Поделись привычками с друзьями: вместе соблюдать проще."],"exercise_slugs":[],"specialist_kk":"Маманға жүгінудің қажеті жоқ.","specialist_ru":"Обращаться к специалисту не нужно."}]'::jsonb, 'published', (select id from public.topics where slug = 'sleep-nutrition'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('career-anxiety', 'Кәсіби белгісіздік', 'Профессиональная неопределённость', 'Болашақ мамандығың туралы ойларыңды бағала. 7 сұрақ, шамамен 3 минут. Жоғары ұпай белгісіздік пен алаңдаушылықтың жоғары екенін көрсетеді.', 'Оцени свои мысли о будущей профессии. 7 вопросов, около 3 минут. Высокий балл означает более сильную неопределённость и тревогу.', 3, '[{"level":"low","min":0,"max":7,"title_kk":"Төмен деңгей: болашақ біршама айқын","title_ru":"Низкий уровень: будущее довольно ясно","summary_kk":"Мамандық туралы ойлар сені көп алаңдатпайды. Бағытың айқынырақ немесе белгісіздікпен тыныш қарым-қатынас жасай аласың.","summary_ru":"Мысли о профессии не слишком тебя тревожат. Либо у тебя довольно чёткое направление, либо ты спокойно относишься к неопределённости.","recommendations_kk":["Құндылықтарыңды жазып қой — таңдау қиындағанда сүйенетін тірек болады.","Өз саласыңда бір тағылымдамаға немесе жобаға қатысып көр.","Мамандығы бар адамдармен танысып, олардың жұмыс күні туралы сұра."],"recommendations_ru":["Запиши свои ценности: они станут опорой, когда выбирать будет трудно.","Попробуй стажировку или проект в своей сфере.","Знакомься с людьми из профессии и расспрашивай про их рабочий день."],"exercise_slugs":[],"specialist_kk":"Маманға жүгінудің қажеті жоқ.","specialist_ru":"Обращаться к специалисту не нужно."},{"level":"medium","min":8,"max":14,"title_kk":"Орташа деңгей: белгісіздік байқалады","title_ru":"Средний уровень: неопределённость заметна","summary_kk":"Болашақ туралы ойлар сені мезгіл-мезгіл алаңдатады. Бұл көптеген студентке таныс күй: белгісіздікті шағын қадамдармен азайтуға болады.","summary_ru":"Мысли о будущем время от времени тебя тревожат. Это знакомо многим студентам: неопределённость можно уменьшать небольшими шагами.","recommendations_kk":["«Мінсіз шешімді» емес, «келесі қадамды» таңда: бір әңгіме, бір курс, бір шағын жоба.","Алаңдаған кезде 5-4-3-2-1 техникасымен назарды қазіргі сәтке қайтар.","Бір ай ішінде бір мамандықты сынап көру үшін шағын тәжірибе жоспарла."],"recommendations_ru":["Выбирай не «идеальное решение», а «следующий шаг»: один разговор, один курс, один мини-проект.","Когда тревожно, возвращай внимание в настоящее с помощью техники 5-4-3-2-1.","Запланируй небольшой эксперимент на месяц, чтобы попробовать одну профессию."],"exercise_slugs":["grounding-54321","emotion-diary"],"specialist_kk":"Егер алаңдаушылық ұйқы мен оқуға кедергі келтірсе, университеттің мансап орталығына немесе психологқа жүгін.","specialist_ru":"Если тревога мешает спать и учиться, обратись в центр карьеры вуза или к психологу."},{"level":"high","min":15,"max":21,"title_kk":"Жоғары деңгей: белгісіздік қатты қысады","title_ru":"Высокий уровень: неопределённость сильно давит","summary_kk":"Мамандық пен болашақ туралы ойлар қазір сені қатты алаңдатып, оқуға да әсер етіп жатыр. Бұл диагноз емес — қолдау мен нақты қадамдар қажет екенінің белгісі.","summary_ru":"Мысли о профессии и будущем сейчас сильно тревожат и влияют даже на учёбу. Это не диагноз, а сигнал, что нужны поддержка и конкретные шаги.","recommendations_kk":["Сенетін адаммен сөйлес: куратормен, мансап орталығымен, отбасыңмен.","Үлкен таңдауды шағын тексеріс қадамдарына бөл: қазір не білгің келеді?","Күн сайын тыныштандыратын жаттығу жасап, ұйқыңды қорға."],"recommendations_ru":["Поговори с человеком, которому доверяешь: куратором, центром карьеры, семьёй.","Раздели большой выбор на маленькие шаги проверки: что ты хочешь узнать прямо сейчас?","Каждый день делай успокаивающее упражнение и защищай сон."],"exercise_slugs":["breathing-box","grounding-54321","emotion-diary"],"specialist_kk":"Психологқа немесе мансап кеңесшісіне жуық арада көріну ұсынылады, әсіресе үмітсіздік сезімі болса.","specialist_ru":"Рекомендуем в ближайшее время обратиться к психологу или карьерному консультанту, особенно если есть чувство безнадёжности."}]'::jsonb, 'published', (select id from public.topics where slug = 'career-anxiety'))
on conflict (slug) do update set title_kk = excluded.title_kk, title_ru = excluded.title_ru, description_kk = excluded.description_kk, description_ru = excluded.description_ru, duration_min = excluded.duration_min, thresholds = excluded.thresholds, status = excluded.status, topic_id = excluded.topic_id;

insert into public.tests (slug, title_kk, title_ru, description_kk, description_ru, duration_min, thresholds, status, topic_id)
values ('self-esteem', 'Өзіне сенімділік деңгейі', 'Уровень уверенности в себе', 'Өзіңе қатынасыңды бағала. 8 сұрақ, шамамен 4 минут. Жоғары ұпай өзіне сенімділіктің жоғары екенін көрсетеді.', 'Оцени своё отношение к себе. 8 вопросов, около 4 минут. Высокий балл означает более высокую уверенность в себе.', 4, '[{"level":"low","min":0,"max":8,"title_kk":"Төмен деңгей: өзіңе сенім әзірге аз","title_ru":"Низкий уровень: уверенности в себе пока мало","summary_kk":"Қазір өзіңе қатал қарап, күшті жақтарыңды аз көріп жүрген сияқтысың. Өзін-өзі бағалау тұрақты жапсырма емес, оны күн сайынғы шағын әрекеттермен нығайтуға болады.","summary_ru":"Сейчас ты, похоже, строг(а) к себе и мало замечаешь свои сильные стороны. Самооценка — не постоянный ярлык, её можно укреплять небольшими ежедневными действиями.","recommendations_kk":["Күн сайын бүгін не жақсы шыққанын 3 нәрсе етіп жаз.","Ішкі сын естігенде: «Досыма не айтар едім?» деп сұра және соны өзіңе айт.","Өзіңді басқамен емес, өткен жылғы өзіңмен салыстыр."],"recommendations_ru":["Каждый день записывай 3 вещи, которые сегодня получились.","Услышав внутреннюю критику, спроси себя: «Что бы я сказал(а) другу?» — и скажи это себе.","Сравнивай себя не с другими, а с собой прошлогодним."],"exercise_slugs":["emotion-diary","breathing-478"],"specialist_kk":"Егер өзіңді жарамсыз сезіну ұзақ тұрса немесе көңіл-күйің түссе, психологқа жүгіну пайдалы болады. Қолдау шынымен көмектеседі.","specialist_ru":"Если чувство «я никуда не гожусь» держится долго или настроение падает, полезно обратиться к психологу. Поддержка действительно помогает."},{"level":"medium","min":9,"max":16,"title_kk":"Орташа деңгей: сенімділік ауытқиды","title_ru":"Средний уровень: уверенность колеблется","summary_kk":"Кейбір жағдайларда өзіңе сенімдісің, кейбірінде күмәндана бастайсың. Бұл — қалыпты көрініс. Күшті жақтарыңды тұрақты көріп отыру сенімділікті нығайтады.","summary_ru":"В одних ситуациях ты уверен(а) в себе, в других начинаешь сомневаться. Это нормальная картина. Умение регулярно видеть свои сильные стороны укрепляет уверенность.","recommendations_kk":["Күшті жақтарыңның тізімін жасап, апта сайын жаңа мысал қос.","Бір рет шағын нәрседе «жоқ» деп айтып көр — шекарамен жаттығу өзіңе деген құрметті арттырады.","Қателікті жеңіліс емес, ақпарат деп қабылдап, одан не үйренгеніңді жаз."],"recommendations_ru":["Составь список сильных сторон и каждую неделю добавляй новый пример.","Попробуй один раз сказать «нет» в чём-то небольшом: тренировка границ повышает уважение к себе.","Воспринимай ошибку как информацию, а не поражение, и запиши, чему она научила."],"exercise_slugs":["emotion-diary"],"specialist_kk":"Маманға жүгінудің қажеті жоқ шығар; күмән ұзақ созылып, көңіл-күй түссе, психологқа жүгін.","specialist_ru":"Скорее всего, к специалисту обращаться не нужно; если сомнения затягиваются и настроение падает, обратись к психологу."},{"level":"high","min":17,"max":24,"title_kk":"Жоғары деңгей: сенімділік жақсы","title_ru":"Высокий уровень: уверенность хорошая","summary_kk":"Сен өзіңе жақсы қарайсың: күшті жақтарыңды көресің, сынды сабырмен қабылдайсың. Бұл — қиындықтарда сенімді тірек.","summary_ru":"Ты хорошо относишься к себе: видишь свои сильные стороны и спокойно принимаешь критику. Это надёжная опора в трудные периоды.","recommendations_kk":["Жетістіктеріңді белгілеп отыр — бұл қиын кезде еске түсіруге көмектеседі.","Басқаға қолдау көрсетуге тырыс: мейірімді сөз екі жаққа да күш береді.","Өзіңе деген сенімділікті жаңа сын-тегеуріндермен қолдап отыр."],"recommendations_ru":["Отмечай свои достижения — они помогут вспомнить о силе в трудный момент.","Поддерживай других: доброе слово даёт силы обоим.","Поддерживай уверенность новыми вызовами."],"exercise_slugs":[],"specialist_kk":"Маманға жүгінудің қажеті жоқ.","specialist_ru":"Обращаться к специалисту не нужно."}]'::jsonb, 'published', (select id from public.topics where slug = 'self-esteem'))
